-- ParadiseRP catalogue extension v4 - 2000 meubles verifies
-- Chaque meuble possede une ligne serveur, un FurnitureData, un .nitro et une icone.
SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE parent_id=VALUES(parent_id),caption_save=VALUES(caption_save),caption=VALUES(caption),page_layout=VALUES(page_layout),icon_color=VALUES(icon_color),icon_image=VALUES(icon_image),min_rank=VALUES(min_rank),order_num=VALUES(order_num),visible='1',enabled='1',club_only='0',vip_only='0';
DELETE FROM catalog_items WHERE page_id BETWEEN 9967100 AND 9967199;
DELETE FROM catalog_pages WHERE id BETWEEN 9967101 AND 9967199 AND id NOT IN (9967102,9967103,9967104,9967107,9967106,9967111,9967112,9967113,9967115,9967116,9967118,9967119,9967120);

ON DUPLICATE KEY UPDATE item_name=VALUES(item_name),public_name=VALUES(public_name),type=VALUES(type),width=VALUES(width),length=VALUES(length),stack_height=VALUES(stack_height),can_stack=VALUES(can_stack),can_sit=VALUES(can_sit),is_walkable=VALUES(is_walkable),sprite_id=VALUES(sprite_id),interaction_type=VALUES(interaction_type),behaviour_data=VALUES(behaviour_data),interaction_modes_count=VALUES(interaction_modes_count),vending_ids=VALUES(vending_ids),allow_lay=VALUES(allow_lay);

COMMIT;
